    fileSha: uploadResult.content?.sha,
    commitSha: uploadResult.commit?.sha,
    uploadCompleted: true,
    uploadTimestamp: uploadResult.uploadTimestamp
  }
}];

// Process ALL items from the merged data
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const data = items[i].json;

  console.log(`Processing item ${i + 1}/${items.length}`);
  console.log('Available fields:', Object.keys(data));

  // Define the 3 image types we need
  const imageTypes = ['banner', 'og', 'social'];

  // Create an item for each image type
  for (let j = 0; j < imageTypes.length; j++) {
    const imageType = imageTypes[j];
    const filename = `${data.slug}-${imageType}.webp`;
    const filePath = `public/images/blog/${data.slug}/${filename}`;

    console.log(`Creating ${imageType} image:`, filename);
    console.log('File path:', filePath);

    results.push({
      json: {
        slug: data.slug,
        filename: filename,
        filePath: filePath,
        base64: data.base64, // This should come from Merge7
        imageType: imageType,
        imageIndex: j,
        originalFilename: filename,
        originalPath: `/images/blog/${data.slug}/${filename}`,
        blogPost: data.blogPost,
        title: data.title,
        description: data.description,
        category: data.category,
        date: data.date
      }
    });
  }
}

console.log(`Processed ${results.length} total images (${items.length} items × 3 image types each)`);
return results;
